    public static int tZeros(emon.Port.Buf b, int n) {
        // The caller's part of the contract: `n` zero bytes to paint on.
        int i = 0;
        while (i < n) {
            emon.Port.bufPush(b, 0);
            i += 1;
        }
        return 0;
    }
    public static int tDec(int emonT, emon.Port.Cells ws, byte[] d, int k, int cols, int rows, int flags, int want, int nbytes, int b0, int b1, int b2, int b3, String msg) {
        emon.Port.Buf out = emon.Port.newBuf();
        tZeros(out, rows * ((cols + 7) / 8));
        int st = Ccitt.ccDecode(d, 0, emon.Port.blobLen(d), k, cols, rows, flags, out, ws);
        emon.Testport.assertEq(st, want, msg);
        if (want == 0) {
            emon.Testport.assertEq(emon.Port.bufLen(out), nbytes, msg);
            if (b0 >= 0) {
                emon.Testport.assertEq(emon.Port.bufAt(out, 0), b0, msg);
            }
            if (b1 >= 0) {
                emon.Testport.assertEq(emon.Port.bufAt(out, 1), b1, msg);
            }
            if (b2 >= 0) {
                emon.Testport.assertEq(emon.Port.bufAt(out, 2), b2, msg);
            }
            if (b3 >= 0) {
                emon.Testport.assertEq(emon.Port.bufAt(out, 3), b3, msg);
            }
        }
        return 0;
    }
